const P22: LessonDef = {
  id: 'm12d22', title: 'C2 Reading & Inference', week: 53, day: 1, month: 12, level: 'C2', xp: 70, duration: '17 min', topic: 'Communication',
  sections: [
    { type: 'intro', title: '📖 Reading Between the Lines',
      content: 'At C2, comprehension goes beyond the literal. INFERENCE means drawing conclusions the text implies but never states: attitude, purpose, irony, unspoken assumptions. Ask: What does the writer ASSUME? What is IMPLIED but not said? What is the writer\'s real ATTITUDE? A single word ("allegedly", "so-called", "admittedly") can reveal a stance the sentence never openly declares.',
      examples: [
        { full: '"The minister, remarkably, found time to attend." (implies surprise/criticism)', translation: '"O ministro, surpreendentemente, arranjou tempo para comparecer." (implica crítica)' },
        { full: '"It was, by all accounts, a triumph." (the writer distances themselves)', translation: '"Foi, ao que dizem, um triunfo." (o autor distancia-se)' },
      ] },
    { type: 'tip', title: '💡 Tip', content: 'Watch for stance markers ("supposedly", "of course", "naturally"), loaded word choice (see connotation), and what is NOT said. Rhetorical questions imply answers; understatement implies more than it says; a shift in tone signals a shift in attitude. Inference questions in exams ask "what does the writer suggest/imply?": the answer is rarely the surface statement.' },
    { type: 'examples', title: '🗣️ Real Examples', sentences: [
      '"He is, if nothing else, persistent." (faint praise → other qualities lacking)',
      '"She claims to have finished." (writer doubts it)',
      '"Naturally, the promise was broken." (writer expected it)',
    ]},
  ],
  stage1: [
    { id:1, type:'multiple_choice', question:"'He claims to have finished' implies the writer:", options:['doubts he finished','is certain he finished','helped him finish','does not care'], answer:'doubts he finished', explanation:"'claims' signals doubt.", xp:10 },
    { id:2, type:'multiple_choice', question:"'Naturally, the promise was broken' implies the writer:", options:['expected it to be broken','was surprised','made the promise','trusts the promiser'], answer:'expected it to be broken', explanation:"'Naturally' = as expected (cynical).", xp:10 },
    { id:3, type:'fill_blank', question:"'She is, ___ else, persistent': faint praise implying she lacks other virtues.", options:['if nothing','if much','if anything','if all'], answer:'if nothing', explanation:"'if nothing else' = at least this one quality.", xp:10 },
    { id:4, type:'translation', question:"What does 'so-called experts' imply?", options:['The writer doubts they are real experts.','They are the best experts.','They are unknown.','They are foreign.'], answer:'The writer doubts they are real experts.', explanation:"'so-called' signals scepticism.", xp:10 },
    { id:5, type:'write', question:"'It was, ___ accounts, a success': a phrase that DISTANCES the writer from the claim. (by all)", options:[], answer:'by all', explanation:"'by all accounts' = according to others, not me.", xp:10 },
    { id:6, type:'multiple_choice', question:"'The meeting, remarkably, started on time' implies:", options:['starting on time is unusual here','the meeting was important','the writer was late','time is short'], answer:'starting on time is unusual here', explanation:"'remarkably' implies it rarely happens.", xp:10 },
    { id:7, type:'fill_blank', question:"'He was polite, ___.' (a word that implies 'but nothing more': at best)", options:['at best','at last','at once','at heart'], answer:'at best', explanation:"'polite at best' implies limited virtue.", xp:15 },
    { id:8, type:'multiple_choice', question:"'Allegedly generous' suggests the generosity is:", options:['claimed but unproven','definitely real','excessive','famous'], answer:'claimed but unproven', explanation:"'allegedly' withholds endorsement.", xp:15 },
    { id:9, type:'translation', question:"What is IMPLIED by 'She did, to her credit, apologise'?", options:['Apologising was better than expected of her.','She apologises often.','She never apologises.','The apology was insincere.'], answer:'Apologising was better than expected of her.', explanation:"'to her credit' implies it was more than one might expect.", xp:15 },
    { id:10, type:'write', question:"'The plan is, ___, ambitious': a stance word implying the writer concedes this before objecting. (admittedly)", options:[], answer:'admittedly', explanation:"'admittedly' concedes a point.", xp:15 },
  ],
  stage2: [
    { id:11, type:'multiple_choice', question:"'The report was, shall we say, optimistic' implies the writer thinks it was:", options:['unrealistically rosy','perfectly accurate','too pessimistic','well written'], answer:'unrealistically rosy', explanation:"'shall we say' softens a criticism, it means over-optimistic.", xp:15 },
    { id:12, type:'fill_blank', question:"Read the stance: 'Predictably, funding was cut.' The writer regards the cut as ___.", options:['unsurprising','shocking','welcome','random'], answer:'unsurprising', explanation:"'Predictably' = the writer expected it.", xp:15 },
    { id:13, type:'translation', question:"What does 'He deigned to reply' imply about the writer's view of him?", options:['The writer sees him as arrogant/condescending.','The writer admires his manners.','The writer thanks him warmly.','The writer envies him.'], answer:'The writer sees him as arrogant/condescending.', explanation:"'deigned' implies he acted as if replying were beneath him.", xp:20 },
    { id:14, type:'multiple_choice', question:"Which sentence IMPLIES criticism most subtly?", options:['The novel is not without its charms.','The novel is charming.','The novel is a masterpiece.','The novel is delightful throughout.'], answer:'The novel is not without its charms.', explanation:"Litotes here damns with faint praise, some charm, but limited.", xp:20 },
    { id:15, type:'write', question:"'The service was, let us say, ___.' A euphemistic gap implying it was actually poor. Suggest a word.", options:[], answer:'unhurried', accept:['leisurely','relaxed'], explanation:"'unhurried/leisurely' euphemistically implies slow/bad service.", xp:15 },
    { id:16, type:'translation', question:"Infer the attitude: 'Ele, como sempre, chegou tarde.'", options:['The writer implies lateness is his habit (mild reproach).','The writer praises his timing.','The writer is surprised.','The writer arrived late too.'], answer:'The writer implies lateness is his habit (mild reproach).', explanation:"'como sempre / as always' implies a recurring failing.", xp:20 },
    { id:17, type:'multiple_choice', question:"'The committee, in its wisdom, chose to do nothing' is:", options:['ironic, the writer thinks the choice was foolish','sincere praise of the committee','a neutral report','a compliment'], answer:'ironic, the writer thinks the choice was foolish', explanation:"'in its wisdom' + 'do nothing' signals irony.", xp:15 },
    { id:18, type:'fill_blank', question:"'She was competent enough.' The word '___' implies she was adequate but not impressive.", options:['enough','very','truly','wholly'], answer:'enough', explanation:"'competent enough' damns with faint praise.", xp:20 },
    { id:19, type:'multiple_choice', question:"What is the UNSTATED assumption in 'Even the critics praised it'?", options:['Critics usually dislike/are hard to please.','Critics never speak.','Critics wrote the work.','Critics are always right.'], answer:'Critics usually dislike/are hard to please.', explanation:"'Even' assumes critics are normally unimpressed.", xp:15 },
    { id:20, type:'translation', question:"Infer: 'A reforma foi, no mínimo, controversa.'", options:['The writer implies it was very controversial (understatement).','The writer thinks it was uncontroversial.','The writer supports the reform.','The writer wrote the reform.'], answer:'The writer implies it was very controversial (understatement).', explanation:"'no mínimo / to say the least' understates a strong view.", xp:20 },
  ],
  stage3: [
    { id:21, type:'multiple_choice', question:"Read: 'The minister assured us, with his customary sincerity, that no promises would be broken.' What does the writer imply?", options:['The minister is habitually insincere; the assurance is worthless.','The minister is genuinely sincere and trustworthy.','The minister rarely speaks in public.','The writer fully believes the assurance.'], answer:'The minister is habitually insincere; the assurance is worthless.', explanation:"'customary sincerity' is ironic, implying insincerity is his custom.", xp:25 },
    { id:22, type:'write', question:"Insert a single stance word to imply the writer DOUBTS the claim: 'The company ___ acted in good faith.' (allegedly)", options:[], answer:'allegedly', accept:['supposedly'], explanation:"'allegedly/supposedly' withholds endorsement.", xp:25 },
    { id:23, type:'translation', question:"Infer the writer's real attitude and translate: 'É verdade que o projeto ficou pronto, três anos depois do prazo e ao triplo do orçamento.'", options:['True, the project was finished, three years late and at triple the budget.','The project was a great success, finished early and under budget.','The project was cancelled before completion.','The project finished on time and on budget.'], answer:'True, the project was finished, three years late and at triple the budget.', explanation:"The concession ('True … finished') is undercut by the damning detail, implied heavy criticism.", xp:30 },
    { id:24, type:'multiple_choice', question:"Which sentence's IMPLICATION is that the speaker disapproves, despite outward neutrality?", options:['The council, ever mindful of its own comfort, met at a five-star resort.','The council met at a conference venue to discuss the budget.','The council held its annual meeting on Tuesday.','The council convened to review the proposals.'], answer:'The council, ever mindful of its own comfort, met at a five-star resort.', explanation:"'ever mindful of its own comfort' + 'five-star resort' imply self-indulgence.", xp:25 },
    { id:25, type:'fill_blank', question:"'His speech was, if a little long, ___ received.' The structure implies overall approval with one reservation. Best word: (warmly)", options:['warmly','coldly','barely','never'], answer:'warmly', explanation:"'if a little long, warmly received' concedes a flaw but affirms success.", xp:25 },
    { id:26, type:'write', question:"Rewrite to IMPLY (not state) that the food was bad: 'The food was ___.' (a euphemism)", options:[], answer:'forgettable', accept:['unremarkable','edible'], explanation:"'forgettable/unremarkable/edible' imply poor quality without saying so.", xp:30 },
    { id:27, type:'translation', question:"Infer and translate the full irony: 'Que sorte a nossa ter, à frente do país, um homem de tão notável modéstia, como ele próprio nunca se cansa de nos recordar.'", options:['How fortunate we are to have, at the head of the country, a man of such remarkable modesty, as he himself never tires of reminding us.','How lucky we are to have a truly modest and humble leader who never boasts.','We are unfortunate to have an immodest leader who boasts constantly.','Our leader is modest and quiet and never speaks of himself at all.'], answer:'How fortunate we are to have, at the head of the country, a man of such remarkable modesty, as he himself never tires of reminding us.', explanation:"The praise of 'modesty' is destroyed by 'as he himself never tires of reminding us': biting irony implying he is vain.", xp:30 },
    { id:28, type:'multiple_choice', question:"What can be INFERRED from 'Unlike his predecessor, he actually reads the reports'?", options:['His predecessor did not read the reports (criticism of both, faint praise of him).','Both men read reports carefully.','He never reads reports.','His predecessor was better.'], answer:'His predecessor did not read the reports (criticism of both, faint praise of him).', explanation:"'Unlike his predecessor … actually' implies the predecessor did not, and only faintly praises him.", xp:25 },
    { id:29, type:'fill_blank', question:"'The apology, ___ it was, came far too late.' A phrase implying the apology was inadequate. (such as)", options:['such as','as good as','far as','so as'], answer:'such as', explanation:"'such as it was' belittles the apology's quality.", xp:25 },
    { id:30, type:'translation', question:"Infer every layer and translate: 'Reconheça-se o mérito: em apenas uma década, e com recursos que muitos considerariam generosos, conseguiu deixar a instituição praticamente como a encontrou.'", options:['Give credit where it is due: in a mere decade, and with resources many would consider generous, he managed to leave the institution much as he found it.','Give credit: in a decade he transformed the institution beyond recognition.','He ruined the institution in only ten years despite huge resources.','With few resources, he improved the institution greatly in a decade.'], answer:'Give credit where it is due: in a mere decade, and with resources many would consider generous, he managed to leave the institution much as he found it.', explanation:"Mock-concession ('Give credit') + 'a mere decade' + 'resources many would consider generous' + 'much as he found it' imply he achieved nothing, heavy irony.", xp:35 },
  ],
}

const P23: LessonDef = {
  id: 'm12d23', title: 'C2 Paraphrase & Summary', week: 53, day: 2, month: 12, level: 'C2', xp: 70, duration: '17 min', topic: 'Communication',
  sections: [
    { type: 'intro', title: '📖 Restating & Condensing',
      content: 'PARAPHRASE restates an idea in entirely different words while keeping the exact meaning. SUMMARY condenses a longer text to its essentials, dropping detail and example. Both are core C2 skills, tested directly in exams and vital for academic writing. A good paraphrase changes vocabulary AND structure (not just a synonym here and there); a good summary is faithful, balanced and far shorter than the original.',
      examples: [
        { full: 'Original: "The scheme, though costly, ultimately paid for itself." → Paraphrase: "Despite its expense, the programme eventually recouped its costs."', translation: 'Reformulação com palavras diferentes, mesmo sentido.' },
        { full: 'Summary keeps the main point, drops the examples.', translation: 'O resumo guarda a ideia central e deixa cair os exemplos.' },
      ] },
    { type: 'tip', title: '💡 Tip', content: 'To PARAPHRASE well: change the vocabulary (synonyms), the grammar (active↔passive, clause↔phrase, nominalise or de-nominalise), and the sentence structure, but never the meaning, and never add your own opinion. To SUMMARISE: identify the thesis and main supporting points, cut examples/repetition/detail, and rewrite in your own words. Both must be accurate above all.' },
    { type: 'examples', title: '🗣️ Real Examples', sentences: [
      '"begin" → "commence"; "because of" → "owing to" (paraphrase vocab)',
      'Active → passive: "They rejected it" → "It was rejected."',
      'Summary: strip the anecdotes, keep the argument.',
    ]},
  ],
  stage1: [
    { id:1, type:'multiple_choice', question:"A good paraphrase changes:", options:['vocabulary AND structure, keeping meaning','only one word','the meaning','nothing important'], answer:'vocabulary AND structure, keeping meaning', explanation:"Change form, keep meaning.", xp:10 },
    { id:2, type:'multiple_choice', question:"A summary should be:", options:['much shorter and faithful','the same length','longer','full of new opinions'], answer:'much shorter and faithful', explanation:"Condensed and accurate.", xp:10 },
    { id:3, type:'fill_blank', question:"Paraphrase 'because of the rain': '___ to the rain' (formal synonym)", options:['owing','thanks','due only','next'], answer:'owing', explanation:"'owing to' paraphrases 'because of'.", xp:10 },
    { id:4, type:'translation', question:"Best paraphrase of 'They rejected the proposal'?", options:['The proposal was turned down.','They accepted the proposal.','The proposal was rejected by them, it was.','They rejected the offer.'], answer:'The proposal was turned down.', explanation:"Passive + synonym, same meaning.", xp:10 },
    { id:5, type:'write', question:"Paraphrase the verb 'begin' with a formal synonym: '___'", options:[], answer:'commence', explanation:"'commence' = begin.", xp:10 },
    { id:6, type:'multiple_choice', question:"Which is a FAITHFUL summary of 'The scheme was costly but eventually profitable'?", options:['The scheme paid off despite its cost.','The scheme was a total failure.','The scheme was cheap and profitable.','The scheme cost a lot of money for the team.'], answer:'The scheme paid off despite its cost.', explanation:"Keeps both ideas, condensed.", xp:10 },
    { id:7, type:'fill_blank', question:"A paraphrase must NOT add the writer's own ___.", options:['opinion','words','synonyms','structure'], answer:'opinion', explanation:"Stay faithful to the source.", xp:15 },
    { id:8, type:'multiple_choice', question:"Which is a POOR paraphrase (too close to the original)?", options:['The plan, although expensive, finally paid for itself.','The plan, though costly, ultimately paid for itself.','Despite its cost, the plan eventually recouped its expense.','Expensive as it was, the plan came good in the end.'], answer:'The plan, although expensive, finally paid for itself.', explanation:"Only swaps a couple of words, barely a paraphrase.", xp:15 },
    { id:9, type:'translation', question:"Best paraphrase of 'It is essential that we act now'?", options:['Immediate action is vital.','We must act, it is essential now.','It is essential to act now, we must.','Acting is not important now.'], answer:'Immediate action is vital.', explanation:"Nominalised, restructured, same meaning.", xp:15 },
    { id:10, type:'write', question:"Summarise in one word the gist of 'It rained heavily all day without stopping': The weather was ___.", options:[], answer:'wet', accept:['rainy','stormy'], explanation:"A one-word condensation of the gist.", xp:15 },
  ],
  stage2: [
    { id:11, type:'multiple_choice', question:"Best paraphrase of 'The findings suggest a strong correlation between the two variables':", options:['The results indicate the two variables are closely linked.','The findings suggest a strong correlation between the variables two.','The two variables have a correlation that is strong, findings suggest.','There is no link between the variables.'], answer:'The results indicate the two variables are closely linked.', explanation:"New vocabulary and structure, same meaning.", xp:15 },
    { id:12, type:'fill_blank', question:"Paraphrase 'in spite of': '___' (one word)", options:['despite','because','therefore','however'], answer:'despite', explanation:"'despite' = in spite of.", xp:15 },
    { id:13, type:'translation', question:"Best summary of 'Although he trained hard for months, endured injuries and doubts, he ultimately won the race'?", options:['After hard preparation and setbacks, he won.','He trained, got hurt, doubted himself and won the race finally after months.','He won a race one day somehow.','He lost the race despite training.'], answer:'After hard preparation and setbacks, he won.', explanation:"Keeps the arc (effort → obstacles → victory), cuts detail.", xp:20 },
    { id:14, type:'multiple_choice', question:"Which summary is UNFAITHFUL (distorts the source)?", options:['The policy failed and should be scrapped. (source: \'The policy had mixed results and needs review.\')','The policy had mixed results and needs review.','The policy\'s results were mixed; a review is needed.','A review is needed, as the policy\'s outcomes were mixed.'], answer:'The policy failed and should be scrapped. (source: \'The policy had mixed results and needs review.\')', explanation:"'failed … scrapped' overstates 'mixed … review': a distortion.", xp:20 },
    { id:15, type:'write', question:"Paraphrase 'a large number of people' more concisely: '___'", options:[], answer:'many', accept:['many people'], explanation:"'many' paraphrases and condenses.", xp:15 },
    { id:16, type:'translation', question:"Best paraphrase of 'The company was forced to close due to mounting debts'?", options:['Growing debts left the firm with no choice but to shut down.','The company closed due to debts that were mounting up.','The company was forced to close because of debts mounting.','The company thrived despite its debts.'], answer:'Growing debts left the firm with no choice but to shut down.', explanation:"Restructured cause-effect, fresh vocabulary.", xp:20 },
    { id:17, type:'multiple_choice', question:"When summarising, you should DROP:", options:['examples and repetition','the main argument','key conclusions','the thesis'], answer:'examples and repetition', explanation:"Cut detail; keep the core.", xp:15 },
    { id:18, type:'fill_blank', question:"Paraphrase (active→passive): 'Critics praised the film' → 'The film ___ by critics.'", options:['was praised','praised','praises','has praise'], answer:'was praised', explanation:"Passive restructuring.", xp:20 },
    { id:19, type:'multiple_choice', question:"Best paraphrase of 'She has a tendency to exaggerate'?", options:['She tends to overstate things.','She has a tendency for exaggeration to happen.','She is tending towards exaggerating tendencies.','She never exaggerates at all.'], answer:'She tends to overstate things.', explanation:"'tends to overstate' = 'has a tendency to exaggerate'.", xp:15 },
    { id:20, type:'translation', question:"Best summary of a paragraph arguing 'free education boosts the economy through a more skilled workforce, greater innovation and higher tax revenue'?", options:['Free education strengthens the economy in several ways.','Free education is about schools and money and jobs and taxes and skills.','Education should be free for everyone forever.','The economy is complicated and education matters.'], answer:'Free education strengthens the economy in several ways.', explanation:"Captures the thesis; drops the three specific mechanisms (detail).", xp:20 },
  ],
  stage3: [
    { id:21, type:'multiple_choice', question:"Choose the best PARAPHRASE of: 'Notwithstanding its initial unpopularity, the measure proved, in the long run, to be both necessary and effective.'", options:['Although it was disliked at first, the measure ultimately turned out to be essential and successful.','Notwithstanding its unpopularity at the start, the measure proved, in the long run, necessary and effective.','The measure was unpopular but necessary and effective in the long run, notwithstanding.','The measure was popular and pointless from the start.'], answer:'Although it was disliked at first, the measure ultimately turned out to be essential and successful.', explanation:"Fully re-worded and restructured while preserving meaning.", xp:25 },
    { id:22, type:'write', question:"Paraphrase 'It is widely believed that…' without 'believed': 'Many ___ that…' ", options:[], answer:'think', accept:['hold','assume','maintain'], explanation:"'Many think/hold that…' paraphrases the impersonal form.", xp:25 },
    { id:23, type:'translation', question:"Best SUMMARY of: 'Embora a globalização tenha aproximado culturas, criado riqueza e acelerado o progresso tecnológico, também aumentou as desigualdades, ameaçou tradições locais e concentrou o poder económico nas mãos de poucos.'", options:['Globalisation has brought major benefits but also serious costs.','Globalisation is about cultures and wealth and technology and problems too.','Globalisation is entirely good for the whole world always.','Globalisation ruined every local tradition everywhere.'], answer:'Globalisation has brought major benefits but also serious costs.', explanation:"Condenses the balanced argument (benefits vs costs) without listing each item.", xp:30 },
    { id:24, type:'multiple_choice', question:"Which paraphrase subtly CHANGES the meaning (and so is wrong)?", options:['Source: \'The drug may help some patients.\' → \'The drug helps patients.\'','Source: \'The drug may help some patients.\' → \'The drug could benefit certain patients.\'','Source: \'The drug may help some patients.\' → \'Some patients might be helped by the drug.\'','Source: \'The drug may help some patients.\' → \'For some patients, the drug may be beneficial.\''], answer:'Source: \'The drug may help some patients.\' → \'The drug helps patients.\'', explanation:"It drops the hedges 'may' and 'some', overstating the claim.", xp:25 },
    { id:25, type:'fill_blank', question:"Paraphrase 'He is not unintelligent' (litotes) plainly: 'He is ___.'", options:['quite clever','stupid','average','silent'], answer:'quite clever', explanation:"'not unintelligent' = quite clever.", xp:25 },
    { id:26, type:'write', question:"Summarise the gist of 'The evidence, while suggestive, falls short of proof' in three words: 'Suggestive, not ___.'", options:[], answer:'conclusive', accept:['proven','proof'], explanation:"'Suggestive, not conclusive' captures the gist.", xp:30 },
    { id:27, type:'translation', question:"Best PARAPHRASE of: 'A recusa do governo em negociar não só prolongou o conflito como minou qualquer confiança que ainda restasse.'", options:['By refusing to negotiate, the government both extended the conflict and destroyed what little trust remained.','The government\'s refusal to negotiate not only prolonged the conflict but also undermined any remaining trust.','The government would not talk, and this was bad for the conflict and trust.','The government negotiated and built trust, ending the conflict.'], answer:'By refusing to negotiate, the government both extended the conflict and destroyed what little trust remained.', explanation:"Recast structure ('By refusing…') and fresh vocabulary, same meaning.", xp:30 },
    { id:28, type:'multiple_choice', question:"Which is the best one-sentence SUMMARY of a long report concluding that a policy 'worked in cities but failed in rural areas, for reasons of infrastructure and funding'?", options:['The policy succeeded in urban areas but failed in rural ones, largely due to infrastructure and funding gaps.','The policy was about cities and villages and money and roads and things.','The policy failed everywhere completely.','The policy was a triumph in every region without exception.'], answer:'The policy succeeded in urban areas but failed in rural ones, largely due to infrastructure and funding gaps.', explanation:"Faithful, balanced, condensed, keeps the contrast and the causes.", xp:25 },
    { id:29, type:'fill_blank', question:"A summary that adds the summariser's own judgement is ___.", options:['unfaithful','concise','accurate','ideal'], answer:'unfaithful', explanation:"Summaries must not editorialise.", xp:25 },
    { id:30, type:'translation', question:"Produce a faithful PARAPHRASE of: 'Ainda que reconheçamos os seus defeitos, seria injusto negar que a reforma melhorou, de forma mensurável, a vida de milhões.'", options:['Even acknowledging its flaws, it would be unfair to deny that the reform measurably improved millions of lives.','Although we recognise its defects, it would be unjust to deny that the reform improved, in a measurable way, the lives of millions.','The reform had flaws but helped millions of people live better lives, we admit.','The reform was flawless and helped everyone in the whole world greatly.'], answer:'Even acknowledging its flaws, it would be unfair to deny that the reform measurably improved millions of lives.', explanation:"Restructured concession and fresh wording, meaning intact, a genuine paraphrase.", xp:35 },
  ],
}

